mapper.select:
select stl.ACCT_NO acctNo,/**账号**/ stl.ACCT_NAME acctName,/**账户名**/ bok.ACCT_TYPE acctTypeCode,/**账户类型Code**/ bok.ACCT_TYPE acctType,/**账户类型**/ de.BASIS basis, /**计息基础**/
(case when de.INT_TYPE ='01'
then FORMAT(CAST(de.RATE * 100 AS DECIMAL(25,4) ),4) else de.BENCHMARK_ID end) as yield, de.INT_TYPE calcType,/**利率类型**/ DATE_FORMAT(de.EFF_DATE,'%Y-%m-%d')as effDate ,/**生效日**/ info.CASH_ID as cashId ,/**现金流代码**/ bok.BOOKSET_ID as booksetId,/**账套代码**/ bok.CCY as ccy /**币种**/ from STL_CAPACCT_INFO stl left join BOK_BOOKSET_CAPACCT_INFO bok on stl.ACCT_NO =bok.ACCT_NO inner join fin_cash_info info on stl.ACCT_NO=info.FINPROD_ID inner join
FIN_RATE_INFO de on info.CASH_ID = de.CASH_ID where 1=1 and bok.ACCT_TYPE is not null
and int.INT_TYPE in
#{item}
and stl.ACCT_NO in
#{item}
AND bok.ACCT_TYPE in
#{item}
